class S3Backend:
    """Amazon S3 storage backend.

    Uses boto3 for S3 operations. Keys are stored at ``{prefix}{key}`` in the
    specified bucket.

    Args:
        bucket: S3 bucket name.
        prefix: Key prefix (default: "").
        region: AWS region (optional).
        endpoint_url: Custom endpoint URL for S3-compatible services (optional).
        access_key: AWS access key ID (optional, falls back to SDK defaults).
        secret_key: AWS secret access key (optional, falls back to SDK defaults).
    """

    def __init__(
        self,
        bucket: str,
        prefix: str = "",
        region: str | None = None,
        endpoint_url: str | None = None,
        access_key: str | None = None,
        secret_key: str | None = None,
    ):
        try:
            import boto3
        except ImportError:
            raise ImportError(
                "boto3 is required for S3Backend. "
                "Install it with: pip install boto3"
            )
        kwargs: dict[str, Any] = {}
        if region:
            kwargs["region_name"] = region
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if access_key and secret_key:
            kwargs["aws_access_key_id"] = access_key
            kwargs["aws_secret_access_key"] = secret_key
        self._client = boto3.client("s3", **kwargs)
        self._bucket = bucket
        self._prefix = prefix

    def _key(self, key: str) -> str:
        return f"{self._prefix}{key}"

    def write(self, key: str, data: bytes) -> None:
        self._client.put_object(Bucket=self._bucket, Key=self._key(key), Body=data)

    def read(self, key: str) -> bytes:
        try:
            response = self._client.get_object(Bucket=self._bucket, Key=self._key(key))
            return response["Body"].read()
        except self._client.exceptions.NoSuchKey:
            raise FileNotFoundError(f"Key not found in S3: {self._key(key)}")

    def exists(self, key: str) -> bool:
        try:
            self._client.head_object(Bucket=self._bucket, Key=self._key(key))
            return True
        except self._client.exceptions.ClientError as e:
            if e.response["Error"]["Code"] == "404":
                return False
            raise

    def delete(self, key: str) -> None:
        if not self.exists(key):
            raise FileNotFoundError(f"Key not found in S3: {self._key(key)}")
        self._client.delete_object(Bucket=self._bucket, Key=self._key(key))

