class GCSBackend:
    """Google Cloud Storage backend.

    Uses google-cloud-storage for GCS operations.

    Args:
        bucket: GCS bucket name.
        prefix: Key prefix (default: "").
        credentials_path: Path to service account credentials JSON (optional).
    """

    def __init__(
        self,
        bucket: str,
        prefix: str = "",
        credentials_path: str | None = None,
    ):
        try:
            from google.cloud import storage
        except ImportError:
            raise ImportError(
                "google-cloud-storage is required for GCSBackend. "
                "Install it with: pip install google-cloud-storage"
            )
        kwargs: dict[str, Any] = {}
        if credentials_path:
            from google.oauth2 import service_account
            credentials = service_account.Credentials.from_service_account_file(credentials_path)
            kwargs["credentials"] = credentials
        client = storage.Client(**kwargs)
        self._bucket = client.bucket(bucket)
        self._prefix = prefix

    def _key(self, key: str) -> str:
        return f"{self._prefix}{key}"

    def write(self, key: str, data: bytes) -> None:
        blob = self._bucket.blob(self._key(key))
        blob.upload_from_string(data)

    def read(self, key: str) -> bytes:
        blob = self._bucket.blob(self._key(key))
        if not blob.exists():
            raise FileNotFoundError(f"Key not found in GCS: {self._key(key)}")
        return blob.download_as_bytes()

    def exists(self, key: str) -> bool:
        blob = self._bucket.blob(self._key(key))
        return blob.exists()

    def delete(self, key: str) -> None:
        blob = self._bucket.blob(self._key(key))
        if not blob.exists():
            raise FileNotFoundError(f"Key not found in GCS: {self._key(key)}")
        blob.delete()

