class SSHBackend:
    """SSH/SFTP storage backend.

    Uses paramiko for SFTP operations.

    Args:
        host: SSH host.
        base_path: Remote base directory.
        port: SSH port (default: 22).
        username: SSH username (optional).
        key_path: Path to SSH private key (optional).
        password: SSH password (optional).
    """

    def __init__(
        self,
        host: str,
        base_path: str,
        port: int = 22,
        username: str | None = None,
        key_path: str | None = None,
        password: str | None = None,
    ):
        try:
            import paramiko
        except ImportError:
            raise ImportError(
                "paramiko is required for SSHBackend. "
                "Install it with: pip install paramiko"
            )
        self._transport = paramiko.Transport((host, port))
        connect_kwargs: dict[str, Any] = {}
        if username:
            connect_kwargs["username"] = username
        if key_path:
            connect_kwargs["pkey"] = paramiko.RSAKey.from_private_key_file(key_path)
        if password:
            connect_kwargs["password"] = password
        self._transport.connect(**connect_kwargs)
        self._sftp = paramiko.SFTPClient.from_transport(self._transport)
        self._base_path = base_path

    def _path(self, key: str) -> str:
        return f"{self._base_path}/{key}"

    def _makedirs(self, remote_path: str) -> None:
        """Create remote directories recursively."""
        parts = remote_path.rsplit("/", 1)
        if len(parts) == 2 and parts[0]:
            parent = parts[0]
            try:
                self._sftp.stat(parent)
            except FileNotFoundError:
                self._makedirs(parent)
                self._sftp.mkdir(parent)

    def write(self, key: str, data: bytes) -> None:
        remote = self._path(key)
        self._makedirs(remote)
        with self._sftp.open(remote, "wb") as f:
            f.write(data)

    def read(self, key: str) -> bytes:
        remote = self._path(key)
        try:
            with self._sftp.open(remote, "rb") as f:
                return f.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"Key not found via SSH: {remote}")

    def exists(self, key: str) -> bool:
        try:
            self._sftp.stat(self._path(key))
            return True
        except FileNotFoundError:
            return False

    def delete(self, key: str) -> None:
        remote = self._path(key)
        try:
            self._sftp.remove(remote)
        except FileNotFoundError:
            raise FileNotFoundError(f"Key not found via SSH: {remote}")

    def close(self) -> None:
        """Close the SSH connection."""
        self._sftp.close()
        self._transport.close()

