class RcloneBackend:
    """Rclone-based storage backend.

    Uses the ``rclone`` CLI for storage operations. Supports any backend
    that rclone supports.

    Args:
        remote: Rclone remote string (e.g., ``"myremote:bucket/path"``).
        config_path: Path to rclone config file, or None for rclone default.
    """

    def __init__(self, remote: str, config_path: str | None = None):
        self._remote = remote.rstrip("/")
        self._config_path = config_path

    def _base_cmd(self) -> list[str]:
        if self._config_path is not None:
            return ["rclone", "--config", self._config_path]
        return ["rclone"]

    def _target(self, key: str) -> str:
        return f"{self._remote}/{key}"

    def write(self, key: str, data: bytes) -> None:
        result = subprocess.run(
            [*self._base_cmd(), "rcat", self._target(key)],
            input=data,
            capture_output=True,
        )
        if result.returncode != 0:
            raise RuntimeError(f"rclone write failed: {result.stderr.decode()}")

    def read(self, key: str) -> bytes:
        result = subprocess.run(
            [*self._base_cmd(), "cat", self._target(key)],
            capture_output=True,
        )
        if result.returncode != 0:
            raise FileNotFoundError(f"Key not found via rclone: {self._target(key)}")
        return result.stdout

    def exists(self, key: str) -> bool:
        result = subprocess.run(
            [*self._base_cmd(), "lsf", self._target(key)],
            capture_output=True,
        )
        return result.returncode == 0 and len(result.stdout.strip()) > 0

    def delete(self, key: str) -> None:
        if not self.exists(key):
            raise FileNotFoundError(f"Key not found via rclone: {self._target(key)}")
        result = subprocess.run(
            [*self._base_cmd(), "delete", self._target(key)],
            capture_output=True,
        )
        if result.returncode != 0:
            raise RuntimeError(f"rclone delete failed: {result.stderr.decode()}")

# %% pts/netrun/02_storage/03__backends.pct.py 9
def validate_backend_imports(backend_type: str) -> None:
    """Validate that required libraries are installed for a backend type.

    Args:
        backend_type: One of "local", "s3", "gcs", "ssh", "rclone".

    Raises:
        ImportError: If required library is not installed.
    """
    match backend_type:
        case "local":
            pass  # stdlib
        case "s3":
            import boto3  # noqa: F401
        case "gcs":
            from google.cloud import storage  # noqa: F401
        case "ssh":
            import paramiko  # noqa: F401
        case "rclone":
            result = subprocess.run(["rclone", "version"], capture_output=True)
            if result.returncode != 0:
                raise ImportError("rclone CLI is required for RcloneBackend. Install from https://rclone.org/")
        case _:
            raise ValueError(f"Unknown backend type: {backend_type}")
